// sharing.js - Core implementation
function generateShareText(gameState, includePuzzleNumber = true) {
  const date = new Date();
  const puzzleNumber = Math.floor((date - new Date(2025, 10, 1)) / 86400000) + 1;

  let header = "Connections Daily";
  if (includePuzzleNumber) {
    header += ` #${puzzleNumber}`;
  }

  const groupEmojis = {
    0: "🟨", // Yellow (Easiest)
    1: "🟩", // Green (Easy)
    2: "🟦", // Blue (Medium)
    3: "🟪"  // Purple (Hardest)
  };

  let shareRows = gameState.foundGroups.map(group => 
    groupEmojis[group.difficulty].repeat(4)
  );

  // Add X marks for mistakes
  if (gameState.mistakes > 0) {
    const mistakeText = "❌ ".repeat(gameState.mistakes);
    shareRows.push(mistakeText.trim());
  }

  return `${header}\n\n${shareRows.join("\n")}\n\nhttps://connections-daily.netlify.app/?utm_source=game&utm_medium=share&utm_campaign=puzzle${puzzleNumber}`;
}

// Copy to clipboard with success notification
function copyToClipboard(text) {
  navigator.clipboard.writeText(text).then(() => {
    showToast("Results copied to clipboard!");
  }).catch(err => {
    console.error('Could not copy text: ', err);
    showToast("Failed to copy to clipboard", "error");
  });
}

// Share to Twitter/X
function shareToTwitter(text) {
  const twitterUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}`;
  window.open(twitterUrl, '_blank');
  showToast("Opening Twitter to share your results!");
}

// Toast notification system
function showToast(message, type = "success") {
  const toast = document.createElement("div");
  toast.className = `toast toast-${type}`;
  toast.textContent = message;
  document.body.appendChild(toast);

  setTimeout(() => {
    toast.classList.add("show");
    setTimeout(() => {
      toast.classList.remove("show");
      setTimeout(() => {
        document.body.removeChild(toast);
      }, 300);
    }, 2500);
  }, 100);
}
```

